        "EntraIdSignInEvents",
        "EntraIdSpnSignInEvents",
        "Event",
        "IdentityDirectoryEvents",
        "IdentityInfo",
        "IdentityLogonEvents",
        "IdentityQueryEvents",
        "MicrosoftGraphActivityLogs",
        "OfficeActivity",
        "SecurityEvent",
        "SigninLogs",
        "Syslog",
