      query: '// [IP-P5] Alerts and threat intel on the IP \u2014 Pivot / IP address\n// sentinel-pivot-rules 0.2.0. Parameters: {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}\nlet Value = trim(@"\\s", @"{{VALUE}}");\nlet T0 = coalesce(todatetime(@"{{T0}}"), now());\nlet Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 43200) * 1m; // default: 30d\nlet After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // default: 1d\nlet StartTimestamp = T0 - Before;\nlet EndTimestamp = T0 + After;\n\nunion isfuzzy=true\n// @sentinel-only:begin\n(\n    SecurityAlert\n    | where TimeGenerated between (StartTimestamp .. EndTimestamp)\n    | where Entities has Value or CompromisedEntity == Value\n    | summarize arg_max(TimeGenerated, AlertName, AlertSeverity, ProductName, CompromisedEntity, Status) by SystemAlertId\n    | project TimeGenerated, Source = "SecurityAlert", Title = AlertName, Severity = AlertSeverity, Provider = ProductName,\n        Detail = strcat(CompromisedEntity, " \xB7 ", Status), Reference = SystemAlertId\n),\n// @sentinel-only:end\n(\n    AlertEvidence\n    | where TimeGenerated between (StartTimestamp .. EndTimestamp)\n    | where RemoteIP == Value or LocalIP == Value\n    | summarize arg_min(TimeGenerated, Title, Severity, ServiceSource, EntityType, EvidenceRole, DeviceName) by AlertId\n    | project TimeGenerated, Source = "AlertEvidence", Title, Severity, Provider = ServiceSource,\n        Detail = strcat(EntityType, " \xB7 ", EvidenceRole, " \xB7 ", DeviceName), Reference = AlertId\n)\n// @sentinel-only:begin\n, (\n    ThreatIntelIndicators\n    | where TimeGenerated between ((StartTimestamp - 60d) .. EndTimestamp)\n    | where ObservableValue == Value or Pattern has Value\n    | summarize arg_max(TimeGenerated, *) by Id\n    | where not(IsDeleted) and not(Revoked)\n    | project TimeGenerated, Source = "ThreatIntelIndicators", Title = tostring(Data.name),\n        Severity = strcat("Confidence ", tostring(Confidence)), Provider = SourceSystem,\n        Detail = strcat(Pattern, " \xB7 valid until ", format_datetime(ValidUntil, "yyyy-MM-dd"), iff(IsActive, "", " \xB7 inactive")),\n        Reference = Id\n),\n(\n    AZFWThreatIntel\n    | where TimeGenerated between (StartTimestamp .. EndTimestamp)\n    | where SourceIp == Value or DestinationIp == Value\n    | summarize FirstSeen = min(TimeGenerated), TimeGenerated = max(TimeGenerated), Hits = count(), Ports = make_set(DestinationPort, 5),\n        Peers = make_set(iff(SourceIp == Value, DestinationIp, SourceIp), 5) by Action, ThreatDescription\n    | project TimeGenerated, Source = "AZFWThreatIntel", Title = ThreatDescription, Severity = strcat("Azure Firewall ", Action),\n        Provider = "Azure Firewall (Microsoft threat intel)",\n        Detail = strcat(Hits, " flows since ", format_datetime(FirstSeen, "yyyy-MM-dd HH:mm"), " \xB7 peers ", strcat_array(Peers, ", "),\n            " \xB7 ports ", strcat_array(Ports, ", ")),\n        Reference = ""\n),\n(\n    AADUserRiskEvents\n    | where TimeGenerated between (StartTimestamp .. EndTimestamp)\n    | where IpAddress == Value\n    | summarize arg_max(TimeGenerated, *) by Id\n    | extend Provider = strcat("Entra ID Protection (", Source, ")")\n    | project TimeGenerated, Source = "AADUserRiskEvents", Title = RiskEventType, Severity = RiskLevel, Provider,\n        Detail = strcat(UserPrincipalName, " \xB7 ", RiskState, " \xB7 ", DetectionTimingType, iff(isnotempty(RiskDetail) and RiskDetail != "none", strcat(" \xB7 ", RiskDetail), "")),\n        Reference = Id\n)\n// @sentinel-only:end\n| sort by TimeGenerated desc',
      queryDefender: '// [IP-P5] Alerts and threat intel on the IP \u2014 Pivot / IP address\n// sentinel-pivot-rules 0.2.0. Parameters: {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}\nlet Value = trim(@"\\s", @"{{VALUE}}");\nlet T0 = coalesce(todatetime(@"{{T0}}"), now());\nlet Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 43200) * 1m; // default: 30d\nlet After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // default: 1d\nlet StartTimestamp = T0 - Before;\nlet EndTimestamp = T0 + After;\n\nunion isfuzzy=true\n(\n    AlertEvidence\n    | where Timestamp between (StartTimestamp .. EndTimestamp)\n    | where RemoteIP == Value or LocalIP == Value\n    | summarize arg_min(Timestamp, Title, Severity, ServiceSource, EntityType, EvidenceRole, DeviceName) by AlertId\n    // Defender XDR: alert title, severity, category and detection source (AlertInfo, one row per alert)\n    | lookup kind=leftouter (\n        AlertInfo\n        | where Timestamp between ((StartTimestamp - 1d) .. EndTimestamp)\n        | summarize InfoTitle = take_any(Title), InfoSeverity = take_any(Severity), Category = take_any(Category),\n            DetectionSource = take_any(DetectionSource), AttackTechniques = take_any(AttackTechniques) by AlertId\n      ) on AlertId\n    | extend Title = coalesce(InfoTitle, Title), Severity = coalesce(InfoSeverity, Severity),\n        ServiceSource = strcat(ServiceSource, iff(isnotempty(DetectionSource), strcat(" / ", DetectionSource), "")),\n        EvidenceRole = strcat(EvidenceRole, iff(isnotempty(Category), strcat(" \xB7 ", Category), ""),\n            iff(isnotempty(AttackTechniques) and AttackTechniques != "[]", strcat(" \xB7 ", AttackTechniques), ""))\n    | project Timestamp, Source = "AlertEvidence", Title, Severity, Provider = ServiceSource,\n        Detail = strcat(EntityType, " \xB7 ", EvidenceRole, " \xB7 ", DeviceName), Reference = AlertId\n)\n| sort by Timestamp desc',
      source: "rules/ip/IP-P5.yaml"
