    "AADNonInteractiveUserSignInLogs", "ResultDescription", "AC-P1, AC-P3, AC-P5, AC-P9, AC-S1, AC-S2, AC-T1",
    "AADNonInteractiveUserSignInLogs", "ResultType", "AC-P1, AC-P3, AC-P5, AC-P9, AC-S1, AC-S2, AC-T1",
    "AADNonInteractiveUserSignInLogs", "RiskLevelDuringSignIn", "AC-P1, AC-P3, AC-P5, AC-P9, AC-S1, AC-S2, AC-T1",
