      query: '// [EM-P4] URLs and attachments of the messages \u2014 Pivot / E-mail address\n// sentinel-pivot-rules 0.2.0. Parameters: {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}\nlet Value = trim(@"\\s", @"{{VALUE}}");\nlet T0 = coalesce(todatetime(@"{{T0}}"), now());\nlet Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 240) * 1m; // default: 4h\nlet After = coalesce(tolong(@"{{AFTER_MIN}}"), 60) * 1m; // default: 1h\nlet StartTimestamp = T0 - Before;\nlet EndTimestamp = T0 + After;\n// Email address indicator.\nlet ValueMail = tolower(Value);\nlet ValueMailDomain = tostring(split(ValueMail, "@")[1]);\nlet ValueMailLocal = tostring(split(ValueMail, "@")[0]);\nlet Msgs = EmailEvents\n    | where TimeGenerated between (StartTimestamp .. EndTimestamp)\n    | where RecipientEmailAddress =~ ValueMail or SenderFromAddress =~ ValueMail or SenderMailFromAddress =~ ValueMail\n    | summarize MailTime = min(TimeGenerated), Subject = take_any(Subject), Sender = take_any(SenderFromAddress) by NetworkMessageId;\nlet Clicks = UrlClickEvents\n    | where TimeGenerated between (StartTimestamp .. now())\n    | summarize Clicks = count(), Clickers = make_set(AccountUpn, 10) by NetworkMessageId, Url;\nunion isfuzzy=true\n(\n    EmailUrlInfo\n    | where TimeGenerated between (StartTimestamp .. EndTimestamp)\n    | join kind=inner (Msgs) on NetworkMessageId\n    | join kind=leftouter (Clicks) on NetworkMessageId, Url\n    | project MailTime, Sender, Subject, Kind = "URL", Item = Url, Info = strcat(UrlDomain, " \xB7 ", UrlLocation),\n        SHA256 = "", Threat = "", Clicks = coalesce(Clicks, 0), Clickers, NetworkMessageId\n),\n(\n    EmailAttachmentInfo\n    | where TimeGenerated between (StartTimestamp .. EndTimestamp)\n    | join kind=inner (Msgs) on NetworkMessageId\n    | project MailTime, Sender, Subject, Kind = "Attachment", Item = FileName, Info = strcat(FileType, " \xB7 ", tostring(FileSize), " bytes"),\n        SHA256, Threat = strcat(ThreatTypes, " ", ThreatNames), Clicks = long(null), Clickers = dynamic(null), NetworkMessageId\n)\n| sort by MailTime asc, Kind asc',
      queryDefender: '// [EM-P4] URLs and attachments of the messages \u2014 Pivot / E-mail address\n// sentinel-pivot-rules 0.2.0. Parameters: {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}\nlet Value = trim(@"\\s", @"{{VALUE}}");\nlet T0 = coalesce(todatetime(@"{{T0}}"), now());\nlet Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 240) * 1m; // default: 4h\nlet After = coalesce(tolong(@"{{AFTER_MIN}}"), 60) * 1m; // default: 1h\nlet StartTimestamp = T0 - Before;\nlet EndTimestamp = T0 + After;\n// Email address indicator.\nlet ValueMail = tolower(Value);\nlet ValueMailDomain = tostring(split(ValueMail, "@")[1]);\nlet ValueMailLocal = tostring(split(ValueMail, "@")[0]);\nlet Msgs = EmailEvents\n    | where Timestamp between (StartTimestamp .. EndTimestamp)\n    | where RecipientEmailAddress =~ ValueMail or SenderFromAddress =~ ValueMail or SenderMailFromAddress =~ ValueMail\n    | summarize MailTime = min(Timestamp), Subject = take_any(Subject), Sender = take_any(SenderFromAddress) by NetworkMessageId;\nlet Clicks = UrlClickEvents\n    | where Timestamp between (StartTimestamp .. now())\n    | summarize Clicks = count(), Clickers = make_set(AccountUpn, 10) by NetworkMessageId, Url;\nunion isfuzzy=true\n(\n    EmailUrlInfo\n    | where Timestamp between (StartTimestamp .. EndTimestamp)\n    | join kind=inner (Msgs) on NetworkMessageId\n    | join kind=leftouter (Clicks) on NetworkMessageId, Url\n    | project MailTime, Sender, Subject, Kind = "URL", Item = Url, Info = strcat(UrlDomain, " \xB7 ", UrlLocation),\n        SHA256 = "", Threat = "", Clicks = coalesce(Clicks, 0), Clickers, NetworkMessageId\n),\n(\n    EmailAttachmentInfo\n    | where Timestamp between (StartTimestamp .. EndTimestamp)\n    | join kind=inner (Msgs) on NetworkMessageId\n    | project MailTime, Sender, Subject, Kind = "Attachment", Item = FileName, Info = strcat(FileType, " \xB7 ", tostring(FileSize), " bytes"),\n        SHA256, Threat = strcat(ThreatTypes, " ", ThreatNames), Clicks = long(null), Clickers = dynamic(null), NetworkMessageId\n)\n| sort by MailTime asc, Kind asc',
