      query: '// [AP-P1] Application consents, permissions and secrets \u2014 Pivot / Application\n// sentinel-pivot-rules 0.2.0. Parameters: {{VALUE}}, {{T0}}, {{BEFORE_MIN}}, {{AFTER_MIN}}\nlet Value = trim(@"\\s", @"{{VALUE}}");\nlet T0 = coalesce(todatetime(@"{{T0}}"), now());\nlet Before = coalesce(tolong(@"{{BEFORE_MIN}}"), 43200) * 1m; // default: 30d\nlet After = coalesce(tolong(@"{{AFTER_MIN}}"), 1440) * 1m; // default: 1d\nlet StartTimestamp = T0 - Before;\nlet EndTimestamp = T0 + After;\n// Application indicator: AppId (GUID), service principal ID or display name.\nlet ValueApp = Value;\nlet ValueAppLower = tolower(Value);\n// Entra ID sign-ins of applications (service principals) and managed identities, normalized:\n// - Sentinel: AADServicePrincipalSignInLogs and AADManagedIdentitySignInLogs;\n// - Defender XDR: EntraIdSpnSignInEvents (IsManagedIdentity tells them apart), read only for the type the Sentinel\n//   tables do not provide over the period (no duplicates in the unified portal).\n// "@sentinel-only" blocks (Sentinel tables) are removed from the Defender XDR variant, which then reads only EntraIdSpnSignInEvents.\n// Parameters: start, end, app (AppId, ServicePrincipalId or name; empty = all), ip (empty = all).\nlet _SpnSignins = (start:datetime, end:datetime, app:string, ip:string) {\n    let _HasSpn = toscalar(union isfuzzy=true\n        // @sentinel-only:begin\n        (AADServicePrincipalSignInLogs | where TimeGenerated between ((start - 1d) .. end) | take 1 | project Present = 1),\n        // @sentinel-only:end\n        (print Present = 0)\n        | summarize max(Present)) == 1;\n    let _HasMi = toscalar(union isfuzzy=true\n        // @sentinel-only:begin\n        (AADManagedIdentitySignInLogs | where TimeGenerated between ((start - 1d) .. end) | take 1 | project Present = 1),\n        // @sentinel-only:end\n        (print Present = 0)\n        | summarize max(Present)) == 1;\n    union isfuzzy=true\n    // @sentinel-only:begin\n    (\n        AADServicePrincipalSignInLogs\n        | where TimeGenerated between (start .. end)\n        | where isempty(app) or AppId == app or ServicePrincipalId == app or ServicePrincipalName =~ app\n        | where isempty(ip) or IPAddress == ip\n        | project TimeGenerated, SourceTable = "AADServicePrincipalSignInLogs", SignInType = "Service principal", ServicePrincipalName,\n            ServicePrincipalId, AppId, ResourceDisplayName, ResultType, IPAddress, Location, Credential = ClientCredentialType,\n            AppOwnerTenantId, HomeTenantId = AADTenantId\n    ),\n    (\n        AADManagedIdentitySignInLogs\n        | where TimeGenerated between (start .. end)\n        | where isempty(app) or AppId == app or ServicePrincipalId == app or ServicePrincipalName =~ app\n        | where isempty(ip) or IPAddress == ip\n        | project TimeGenerated, SourceTable = "AADManagedIdentitySignInLogs", SignInType = "Managed identity", ServicePrincipalName,\n            ServicePrincipalId, AppId, ResourceDisplayName, ResultType, IPAddress, Location, Credential = "Managed identity",\n            AppOwnerTenantId, HomeTenantId = TenantId\n    ),\n    // @sentinel-only:end\n    (\n        EntraIdSpnSignInEvents\n        | where Timestamp between (start .. end)\n        | extend SignInType = iff(IsManagedIdentity, "Managed identity", "Service principal")\n        | where (SignInType == "Service principal" and not(_HasSpn)) or (SignInType == "Managed identity" and not(_HasMi))\n        | where isempty(app) or ApplicationId == app or ServicePrincipalId == app or ServicePrincipalName =~ app or Application =~ app\n        | where isempty(ip) or IPAddress == ip\n        | project TimeGenerated = Timestamp, SourceTable = "EntraIdSpnSignInEvents", SignInType, ServicePrincipalName = coalesce(ServicePrincipalName, Application),\n            ServicePrincipalId, AppId = ApplicationId, ResourceDisplayName, ResultType = tostring(ErrorCode), IPAddress, Location = Country,\n            Credential = iff(IsManagedIdentity, "Managed identity", iff(IsConfidentialClient, "Confidential client", "Public client")),\n            AppOwnerTenantId = "", HomeTenantId = ResourceTenantId\n    )\n    | extend Succeeded = ResultType == "0"\n    // Application origin: Microsoft publisher, application of this tenant, or application of another tenant (third-party multi-tenant)\n    | extend AppOrigin = case(AppOwnerTenantId in ("f8cdef31-a31e-4b4a-93e4-5f571e91255a", "72f988bf-86f1-41af-91ab-2d7cd011db47"), "Microsoft (first-party)",\n        SignInType == "Managed identity", "Tenant managed identity",\n        isempty(AppOwnerTenantId), "",\n        AppOwnerTenantId == HomeTenantId, "Tenant application",\n        "Other-tenant application")\n};\nlet Ops = dynamic(["Consent to application", "Add delegated permission grant", "Add app role assignment grant to user",\n    "Add app role assignment to service principal", "Add service principal", "Add service principal credentials",\n    "Add owner to application", "Add owner to service principal", "Update application", "Add application"]);\n// CloudAppEvents is used only when AuditLogs is missing for the period: otherwise the same operations would appear twice\nlet HasAudit = toscalar(union isfuzzy=true\n    // @sentinel-only:begin\n    (AuditLogs | where TimeGenerated between ((StartTimestamp - 1d) .. EndTimestamp) | take 1 | project Present = 1),\n    // @sentinel-only:end\n    (print Present = 0)\n    | summarize max(Present)) == 1;\nunion isfuzzy=true\n// @sentinel-only:begin\n(\n    AuditLogs\n    | where TimeGenerated between (StartTimestamp .. EndTimestamp)\n    | where OperationName in (Ops) or OperationName has "Certificates and secrets management"\n    | where TargetResources has ValueApp or AdditionalDetails has ValueApp\n    | extend Changes = tostring(TargetResources[0].modifiedProperties)\n    | project TimeGenerated, Source = "AuditLogs", OperationName, Result,\n        Initiator = coalesce(tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName)),\n        InitiatorIP = tostring(InitiatedBy.user.ipAddress),\n        Target = tostring(TargetResources[0].displayName),\n        ConsentType = extract(@"ConsentType: (\\w+)", 1, Changes),\n        IsAdminConsent = extract(@"IsAdminConsent[^A-Za-z]+(True|False)", 1, Changes),\n        Scopes = extract_all(@"Scope: ([^,\\]]+)", Changes),\n        Changes = substring(Changes, 0, 1500)\n),\n// @sentinel-only:end\n(\n    CloudAppEvents\n    | where TimeGenerated between (StartTimestamp .. EndTimestamp)\n    | where not(HasAudit)\n    | where ActionType has_any (Ops) or ActionType has "Certificates and secrets management"\n    | where RawEventData has ValueApp\n    | extend Changes = tostring(RawEventData.ModifiedProperties)\n    | project TimeGenerated, Source = "CloudAppEvents", OperationName = ActionType, Result = tostring(RawEventData.ResultStatus),\n        Initiator = coalesce(tostring(RawEventData.UserId), AccountDisplayName), InitiatorIP = IPAddress, Target = ObjectName,\n        ConsentType = extract(@"ConsentType: (\\w+)", 1, Changes),\n        IsAdminConsent = extract(@"IsAdminConsent[^A-Za-z]+(True|False)", 1, Changes),\n        Scopes = extract_all(@"Scope: ([^,\\]]+)", Changes),\n        Changes = substring(Changes, 0, 1500)\n),\n(\n    _SpnSignins(StartTimestamp, EndTimestamp, ValueApp, "")\n    | summarize arg_min(TimeGenerated, ServicePrincipalName, Credential, SourceTable), Signins = count(), LastSeen = max(TimeGenerated)\n        by ResourceDisplayName, IPAddress, Succeeded\n    | project TimeGenerated, Source = SourceTable, OperationName = strcat("Service principal sign-in to ", ResourceDisplayName),\n        Result = iff(Succeeded, "Success", "Failed"), Initiator = ServicePrincipalName, InitiatorIP = IPAddress, Target = ResourceDisplayName,\n        ConsentType = "", IsAdminConsent = "", Scopes = dynamic([]),\n        Changes = strcat(Signins, " sign-in(s) until ", format_datetime(LastSeen, "yyyy-MM-dd HH:mm"), " \xB7 ", Credential)\n)\n| sort by TimeGenerated asc',
