var injected = false;
function injectStyles() {
  if (injected) return;
  injected = true;
  const style = document.createElement("style");
  style.id = `${CSS_PREFIX}-styles`;
  style.textContent = [
    buttonStyles,
    popupStyles,
    notificationStyles,
    pivotStyles,
    caseViewStyles,
    reportDialogStyles
  ].join("\n");
  document.head.appendChild(style);
}

