    const section = t("settings.migration.title");
    const message = t("settings.cases.confirmDeleteAll", { cases: before.cases, runs: before.runs }) + (oldHistory ? t("settings.cases.confirmDeleteAllOld", { section }) : "");
    if (!window.confirm(message)) return;
    const r = deleteAllCaptureData();
