    casesResult.textContent = t("settings.cases.deletedAll", { cases: r.cases, runs }) + (r.failed > 0 ? t("settings.cases.deletedAllPartial", { n: r.failed }) : "") + (hasOldSnapshots() ? t("settings.cases.deletedAllOld", { section }) : "");
    casesResult.hidden = false;
